+	var proto = { a: 1, b: 2 };
+	var obj = { b: 'own', c: 3 };
+
+	assert.strictEqual(setPrototypeOf.mixinProperties(obj, proto), obj);
+	assert.strictEqual(obj.a, 1);
+	assert.strictEqual(obj.b, 'own');
+	assert.strictEqual(obj.c, 3);
+});
+
