+	var base = { inherited: true };
+	var proto = Object.create(base);
+	proto.own = 'yes';
+
+	var obj = {};
+	setPrototypeOf.mixinProperties(obj, proto);
+
+	assert.strictEqual(obj.own, 'yes');
+	assert.strictEqual(obj.inherited, true);
+});

