+		assert.strictEqual(typeof Reflect.setPrototypeOf, 'function');
+
+		var proto = { y: 1 };
+		var obj = {};
+		assert.strictEqual(Reflect.setPrototypeOf(obj, proto), true);
+		assert.strictEqual(Object.getPrototypeOf(obj), proto);
